{{(() => {
  // As the console's order box: the goods, then what Fulfilya keeps (2026-10-02).
  // Total = Amount; goods = total - delivery - fees, from the stored fee lines.
  const en = appsmith.store.bo_lang === 'en';
  const d = GetOrderDetails.data[0] || {};
  const num = (x) => { const v = Number(String(x ?? '').replace(',', '.').replace('$', '')); return isNaN(v) ? 0 : v; };
  const eur = (v) => v.toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
  const delivery = num(d.delivery_fee), fee = num(d.cod_fee), declared = num(d.declared_fee), total = num(d.amount);
  if (d.delivery_fee == null && d.cod_fee == null) return '-';
  // "Обявена стойност": the value the merchant declared, and its fee (0 € on a free trial).
  const dv = num(d.declared_value) / 100;
  const dvText = dv > 0 ? ' · ' + (en ? 'declared value ' : 'обявена стойност ') + eur(dv) + ' (' + (en ? 'fee ' : 'такса ') + eur(declared) + ')' : '';
  const delText = (en ? 'delivery ' : 'доставка ') + eur(delivery);
  // Nothing collected = no наложен платеж, so no COD fee line (Ico, 2026-10-02).
  if (d.payer === 'nothing') return (en ? 'Invoiced to you: ' : 'Фактурира се: ') + delText + dvText + ' = ' + eur(delivery + declared);
  const fees = delText + ' · ' + (en ? 'COD fee ' : 'такса НП ') + eur(fee) + dvText;
  if (d.payment_method !== 'COD') return delText + dvText;
  const goods = Math.max(0, total - delivery - fee - declared);
  return (en ? 'COD amount (goods) ' : 'Стока (наложен платеж) ') + eur(goods) + ' · ' + fees;
})()}}
